import { Component, signal } from '@angular/core';
import { email, form, required } from '@angular/forms/signals';

import {
    StepperContainer,
    StepperQuicknav,
    Onboarding,
    StepperSummary,
    StepperSection,
    StepperStep,
    StepperControl,
    LIB_FORM_STEPPER_CONFIG,
    LIB_FORM_STEPPER_DEFAULT_CONFIG,
} from '@ds-design-system/ui-components/form-stepper';
import { Meta, moduleMetadata, StoryObj } from '@storybook/angular-vite';

// 1. Définition du composant hôte de démonstration
interface DemoFormModel {
    identity: { firstName: string; lastName: string };
    contact: { email: string };
    address: { street: string; city: string };
    preferences: { newsletter: boolean | undefined };
}

@Component({
    selector: 'demo-stepper-host',
    standalone: true,
    imports: [
        StepperContainer,
        StepperQuicknav,
        Onboarding,
        StepperSummary,
        StepperSection,
        StepperStep,
        StepperControl,
    ],
    providers: [
        { provide: LIB_FORM_STEPPER_CONFIG, useValue: LIB_FORM_STEPPER_DEFAULT_CONFIG },
    ],
    template: `
    <lib-form-stepper-container [libFormStepperNoSubmitButton]="false" [libFormStepperDisabled]="isSubmitting()">

      <!-- Page d'onboarding -->
      <ng-template libFormStepperOnboarding libFormStepperOnboardingTitle="Bienvenue"
          libFormStepperOnboardingIcon="libicon-vague" libFormStepperOnboardingPath="bienvenue">
          <h2>Créons votre profil</h2>
          <p>Ce petit formulaire prend environ 2 minutes.</p>
      </ng-template>

      <!-- Section Identité -->
      <div libFormStepperSection [libFormStepperSectionField]="demoForm.identity" libFormStepperTitle="Identité"
          libFormStepperIcon="libicon-compte">

          <ng-template libFormStepperStep [libFormStepperStepField]="demoForm.identity.firstName"
              libFormStepperTitle="Prénom" libFormStepperShortTitle="Prénom" libFormStepperPath="prenom">
              <label>
                  Prénom
                  <input libFormStepperControl type="text" [value]="demoForm.identity.firstName().value()"
                      (input)="demoForm.identity.firstName().value.set($any($event.target).value)" />
              </label>
          </ng-template>

          <ng-template libFormStepperStep [libFormStepperStepField]="demoForm.identity.lastName" libFormStepperTitle="Nom"
              libFormStepperShortTitle="Nom" libFormStepperPath="nom">
              <label>
                  Nom
                  <input libFormStepperControl type="text" [value]="demoForm.identity.lastName().value()"
                      (input)="demoForm.identity.lastName().value.set($any($event.target).value)" />
              </label>
          </ng-template>
      </div>

      <!-- Section Contact -->
      <div libFormStepperSection [libFormStepperSectionField]="demoForm.contact" libFormStepperTitle="Contact"
          libFormStepperIcon="libicon-mail">

          <ng-template libFormStepperStep [libFormStepperStepField]="demoForm.contact.email"
              libFormStepperTitle="Adresse email" libFormStepperShortTitle="Email" libFormStepperPath="email">
              <label>
                  Email
                  <input libFormStepperControl type="email" [value]="demoForm.contact.email().value()"
                      (input)="demoForm.contact.email().value.set($any($event.target).value)" />
              </label>
          </ng-template>
      </div>

      <!-- Section Adresse -->
      <div libFormStepperSection [libFormStepperSectionField]="demoForm.address" libFormStepperTitle="Adresse"
          libFormStepperIcon="libicon-pin-geoloc">

          <ng-template libFormStepperStep [libFormStepperStepField]="demoForm.address.street" libFormStepperTitle="Rue"
              libFormStepperShortTitle="Rue" libFormStepperPath="rue">
              <label>
                  Rue
                  <input libFormStepperControl type="text" [value]="demoForm.address.street().value()"
                      (input)="demoForm.address.street().value.set($any($event.target).value)" />
              </label>
          </ng-template>

          <ng-template libFormStepperStep [libFormStepperStepField]="demoForm.address.city" libFormStepperTitle="Ville"
              libFormStepperShortTitle="Ville" libFormStepperPath="ville">
              <label>
                  Ville
                  <input libFormStepperControl type="text" [value]="demoForm.address.city().value()"
                      (input)="demoForm.address.city().value.set($any($event.target).value)" />
              </label>
          </ng-template>
      </div>

      <!-- Section Préférences -->
      <div libFormStepperSection [libFormStepperSectionField]="demoForm.preferences" libFormStepperTitle="Préférences"
          libFormStepperIcon="libicon-parametres">

          <ng-template libFormStepperStep [libFormStepperStepField]="demoForm.preferences.newsletter"
              [libFormStepperOptions]="{ path: 'newsletter', title: 'Newsletter', autoNextOnValueChange: true }">
              <fieldset>
                  <legend>Souhaitez-vous recevoir notre newsletter ?</legend>
                  <label>
                      <input type="radio" name="newsletter"
                          [checked]="demoForm.preferences?.newsletter()?.value() === true"
                          (change)="demoForm.preferences?.newsletter()?.value?.set(true)" />
                      Oui
                  </label>
                  <label>
                      <input type="radio" name="newsletter"
                          [checked]="demoForm.preferences?.newsletter()?.value() === false"
                          (change)="demoForm.preferences?.newsletter()?.value?.set(false)" />
                      Non
                  </label>
              </fieldset>
          </ng-template>
      </div>

      <!-- Page Récapitulatif -->
      <ng-template libFormStepperSummary libFormStepperSummaryTitle="Récapitulatif" libFormStepperSummaryIcon="libicon-check"
          libFormStepperSummaryPath="recapitulatif">
          <h2>Vérifiez vos informations</h2>
          <lib-form-stepper-quicknav [libFormStepperCompact]="false"></lib-form-stepper-quicknav>
      </ng-template>

    </lib-form-stepper-container>
  `
})
class DemoStepperHostComponent {
    readonly model = signal<DemoFormModel>({
        identity: { firstName: '', lastName: '' },
        contact: { email: '' },
        address: { street: '', city: '' },
        preferences: { newsletter: undefined }
    });

    readonly demoForm = form(this.model, path => {
        required(path.identity.firstName);
        required(path.identity.lastName);
        required(path.contact.email);
        email(path.contact.email);
        required(path.address.street);
        required(path.address.city);
    });

    readonly isSubmitting = signal(false);
}

// 2. Configuration de la Meta Storybook
const meta: Meta<DemoStepperHostComponent> = {
    title: 'Forms/Stepper',
    component: DemoStepperHostComponent,
    decorators: [
        moduleMetadata({
            imports: [DemoStepperHostComponent]
        })
    ],
    tags: ['autodocs'],
    parameters: {
        docs: {
            description: {
                component: 'Composant Stepper multi-étapes réagissant avec les Signals d\'Angular Forms.'
            }
        }
    }
};

export default meta;

type Story = StoryObj<DemoStepperHostComponent>;

// 3. Story Par Défaut
export const Default: Story = {};

import { Signal, TemplateRef } from '@angular/core';
import { LibStepperFieldAdapter } from './utils/stepper-field.adapter';
import { LibIconName } from '@ds-design-system/ui-components/icon';

// Le stepper ne connaît plus Field<T> | FieldTree<T> du tout
export type LibStepperField<T = unknown> = LibStepperFieldAdapter<T>;

export interface LibFormStepperSectionProgression {
    count: number;
    total: number;
}

export interface LibFormStepperExtraPageInfo {
    title: string;
    icon: LibIconName;
    index: number;
}

export interface LibFormStepperExtraPage {
    title: string;
    icon: LibIconName;
    path: string;
    template: TemplateRef<unknown>;
}

export interface LibFormStepperStep {
    id: string;
    title: string;
    shortTitle: string;
    path: string;
    field: LibStepperField;
    template: TemplateRef<unknown>;
    sectionIndex: number;
    sectionProgression?: LibFormStepperSectionProgression;
    autoNext?: boolean;
    hidden?: Signal<boolean>;
    disabled?: Signal<boolean>;
}

export interface LibFormStepperNavSection {
    id: string;
    title: string;
    icon: LibIconName;
    field: LibStepperField;
    steps: Signal<LibFormStepperStep[]>;
    hasQuicknav: boolean;
    noStepsNav?: boolean;
}

export interface LibFormStepperState {
    sectionIndex: number;
    /** Peut valoir -1 (page onboarding) ou steps.length (page summary). */
    stepIndex: number;
    isStepValid: boolean;
    hasPrevStep: boolean;
    hasNextStep: boolean;
    firstStepIndex: number;
    lastStepIndex: number;
    /** Plus grand stepIndex jamais atteint (utilisé pour griser les steps non visitées). */
    maxStepIndexViewed: number;
    /** True quand toutes les steps ont été visitées au moins une fois. */
    allStepsViewed: boolean;
    progress: number;
    onboardingInfo?: LibFormStepperExtraPageInfo;
    summaryInfo?: LibFormStepperExtraPageInfo;
    nav: LibFormStepperNavSection[];
}

export interface libFormStepperMain {
    sectionTitle: string;
    stepTitle: string;
    stepTemplate: TemplateRef<unknown>;
    isFirstStep: boolean;
    isLastStep: boolean;
    isOnboarding: boolean;
    isSummary: boolean;
}

export interface LibFormStepperConfig {
    translations: {
        start: string;
        prev: string;
        next: string;
        submit: string;
        yes: string;
        no: string;
    };
    css: {
        stepTitle: string;
        prev: string;
        next: string;
        submit: string;
    };
}

import { computed, DestroyRef, Directive, ElementRef, inject, input } from '@angular/core';
import { LibStepperStore } from '../stepper.store';

/**
 * Add smart behaviors to a form control inside a step:
 * - autofocus the first control of the step (when the step's field has no value).
 * - prevent form submission when pressing "Enter".
 * - jump to the next step when pressing "Enter" (if the current step is valid).
 *
 * Use `libFormStepperOnEnter` to adjust the behavior.
 *
 * IMPORTANT: relies on `LibStepperStore` being resolvable from this directive's
 * injection context. The host `lib-form-stepper` component MUST render step
 * templates with `[ngTemplateOutletInjector]` pointing to its own injector,
 * otherwise this directive throws a `NullInjectorError`.
 */
@Directive({
  selector: '[libFormStepperControl]',
  host: {
    '(keydown.enter)': 'onEnter($event)'
  }
})
export class StepperControl {
  private readonly store = inject(LibStepperStore);
  private readonly elementRef = inject(ElementRef<HTMLElement>);
  private readonly destroyRef = inject(DestroyRef);

  /**
   * Adjust the directive behavior.
   *
   * @example
   * For a `<textarea>` you probably want:
   * ```ts
   * { preventDefault: false, nextStep: false }
   * ```
   */
  readonly libFormStepperOnEnter = input<Partial<libFormStepperControlOnEnter>>({});

  readonly onEnterConfig = computed<libFormStepperControlOnEnter>(() => ({
    ...LIB_FORM_STEPPER_CONTROL_ON_ENTER_DEFAULT,
    ...this.libFormStepperOnEnter()
  }));

  constructor() {
    // Le step actif au moment de la CRÉATION de cette directive est,
    // par construction, le step dont le template est en train d'être rendu.
    const step = this.store.currentStep();
    if (!step)
      return;

    this.store.registerControlElement(step.path, this.elementRef.nativeElement);
    this.destroyRef.onDestroy(() =>
      this.store.unregisterControlElement(step.path, this.elementRef.nativeElement)
    );
  }

  onEnter(event: Event): void {
    const { preventDefault, nextStep } = this.onEnterConfig();

    // event est typé `Event` (pas `KeyboardEvent`) car les host bindings
    // déclarés en objet littéral ne bénéficient pas de l'inférence DOM
    // qu'a `(keydown.enter)` dans un template. On n'a de toute façon besoin
    // ici que de `preventDefault()`, disponible sur `Event`.
    if (preventDefault) {
      event.preventDefault();
    }

    if (nextStep && this.store.state().isStepValid) {
      this.store.next();
    }
  }
}
export interface libFormStepperControlOnEnter {
  preventDefault: boolean;
  nextStep: boolean;
}

export const LIB_FORM_STEPPER_CONTROL_ON_ENTER_DEFAULT: libFormStepperControlOnEnter = {
  preventDefault: true,
  nextStep: true,
} as const;

