import { Component, computed, DestroyRef, inject, input, signal, ViewEncapsulation } from '@angular/core';
import {
  ConnectedPosition,
  OverlayModule,
} from '@angular/cdk/overlay';
import { StepperSectionIcon } from '../stepper-section-icon/stepper-section-icon';
import { BreakpointObserver } from '@angular/cdk/layout';
import { toSignal } from '@angular/core/rxjs-interop';
import { LibStepperStore } from '../../stepper.store';
import { LibFormStepperNavSection, LibFormStepperStep } from '../../stepper.types';
import { NgTemplateOutlet } from '@angular/common';

const MOBILE_BREAKPOINT = '(max-width: 1023px)';
/**
 * Render the LibFormStepper navigation.
 */
@Component({
  selector: 'lib-form-stepper-nav',
  imports: [OverlayModule, StepperSectionIcon, NgTemplateOutlet],
  templateUrl: './stepper-nav.html',
  styleUrl: './stepper-nav.scss',
  encapsulation: ViewEncapsulation.None,
  host: {
    class: 'lib-form-stepper-nav',
    '[class.lib-form-stepper-nav--mobile]': 'isMobile()'
  }
})
export class StepperNav {
  private readonly store = inject(LibStepperStore);
  private readonly breakpointObserver = inject(BreakpointObserver);
  private readonly destroyRef = inject(DestroyRef);

  /** Determines whether to hide the steps in the "nav" for all sections. */
  readonly libFormStepperNoStepsNav = input(false);

  /** Determines whether to remove the Onboarding link from the "nav". */
  readonly libFormStepperNoOnboardingNav = input(false);

  private readonly breakpointState = toSignal(
    this.breakpointObserver.observe(MOBILE_BREAKPOINT)
  );
  readonly isMobile = computed<boolean>(() => this.breakpointState()?.matches ?? false);

  readonly isMobileOverlayOpen = signal(false);

  readonly mobileOverlayPosition: { left: ConnectedPosition[]; right: ConnectedPosition[] } = {
    left: [
      { originX: 'start', originY: 'bottom', overlayX: 'start', overlayY: 'top' },
      { originX: 'center', originY: 'bottom', overlayX: 'start', overlayY: 'top' }
    ],
    right: [
      { originX: 'end', originY: 'bottom', overlayX: 'end', overlayY: 'top' },
      { originX: 'center', originY: 'bottom', overlayX: 'end', overlayY: 'top' }
    ]
  };

  readonly state = computed(() => this.store.state());

  constructor() {
    // Referme l'overlay mobile dès que le step courant change.
    let previousStepIndex: number | undefined;
    const closeOnNavigate = () => {
      const index = this.store.stepIndex();
      if (previousStepIndex !== undefined && previousStepIndex !== index) {
        this.isMobileOverlayOpen.set(false);
      }
      previousStepIndex = index;
    };
    this.destroyRef.onDestroy(
      // pas de subscription RxJS à nettoyer : l'effect s'auto-détruit avec le composant
      () => { }
    );
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (this as any).__closeEffect = closeOnNavigate;
  }

  /** Index global (dans `store.steps()`) du premier step d'une section, via son index dans `nav`. */
  sectionStepOffset(sectionIndex: number): number {
    return this.store.steps().findIndex(step => step.sectionIndex === sectionIndex);
  }

  navigateByStepIndex(event: Event, stepIndex: number, sectionIndex?: number): void {
    event.stopPropagation();
    if (sectionIndex !== this.state().sectionIndex) {
      this.store.goTo(stepIndex);
    } else if (!this.libFormStepperNoStepsNav()) {
      this.isMobileOverlayOpen.update(open => !open);
    }
  }

  isSectionValid(section: LibFormStepperNavSection, offset: number, maxStepIndexViewed: number): boolean {
    return offset <= maxStepIndexViewed && section.field.valid();
  }

  isStepValid(step: LibFormStepperStep, globalIndex: number, maxStepIndexViewed: number): boolean {
    return globalIndex <= maxStepIndexViewed && step.field.valid();
  }

  isStepDisabled(step: LibFormStepperStep, globalIndex: number, maxStepIndexViewed: number): boolean {
    return globalIndex > maxStepIndexViewed && !step.field.dirty();
  }
}

styleUrlsData.data:
.lib-form-stepper-nav {
    // Color
    --bg-color: #{white};
    --timeline-color: #{lightgray};
    --bullet-color: #{lightgray};

    --text-color__default: #{darkgray};
    --text-color__valid: #{black};

    --valid__bg-color: #{green};
    --valid__text-color: #{white};

    --section-current__bg-color: #{lightblue};
    --section-current__text-color: #{blue};

    --step__underline-color: #{lightgray};

    // Size
    --section__margin: #{1.5rem};
    --section__timeline-width: #{4px};
    --section__timeline-offset: #{3.5rem};

    --section-btn__line-height: #{1.5rem};
    --section-btn__padding-v: #{1.25rem};

    --section-btn__height: calc(var(--section-btn__line-height) + var(--section-btn__padding-v) * 2);
    --section__bullet-offset: calc(var(--section__timeline-offset) - var(--section-btn__height) / 2);

    // Mobile
    --mobile-timeline-width: #{0.5rem};
    --mobile-steps__box-shadow: 0 6px 12px 0 rgba(34, 34, 34, 0.3);
    --mobile-steps__border-color: #{#e1e1e1};
    --mobile-steps__bg-color: #{white};

    // Animation
    --anim-duration: #{250ms};

    // Miscellaneous
    $adjust-step-icon-position: #{0px};

    // Reset
    &-section__btn,
    &-step__btn {
        display: block;
        padding: 0;
        border: none;
        background: none;
        text-align: left;
        font-family: inherit;
        font-size: 100%;

        &:not([disabled]) {
            cursor: pointer;
        }
    }

    // ----- Blocks and Elements -----

    &-sections {
        position: relative;

        &::before {
            content: '';
            position: absolute;
            top: calc(var(--section-btn__height) / 2);
            bottom: calc(var(--section-btn__height) / 2 + var(--section__margin));
            left: calc(var(--section__timeline-offset) - var(--section__timeline-width) / 2);
            border-left: var(--section__timeline-width) solid var(--timeline-color);
        }
    }

    &-section {
        position: relative;
        padding-bottom: var(--section__margin);

        &:not(&--last)::before {
            content: '';
            position: absolute;
            top: calc(var(--section-btn__height) / 2);
            left: calc(var(--section__timeline-offset) - var(--section__timeline-width) / 2);
            border-left: var(--section__timeline-width) solid var(--valid__bg-color);
            height: 0%;
            transition: height var(--anim-duration) ease;
        }

        &__bullet {
            content: '';
            position: absolute;
            top: 0;
            left: var(--section__bullet-offset);
            width: var(--section-btn__height);
            height: var(--section-btn__height);
            line-height: var(--section-btn__height);
            text-align: center;
            box-sizing: border-box;
            border-radius: calc(var(--section-btn__height) / 2);
            border: 4px solid var(--bg-color);
            background-color: var(--bullet-color);
            transition: left var(--anim-duration) ease, width var(--anim-duration) ease,
                background-color var(--anim-duration) ease;
        }

        &__btn {
            position: relative;
            z-index: 1;
            width: 100%;
            padding: var(--section-btn__padding-v) 0;
            padding-left: calc(var(--section__timeline-offset) + var(--section-btn__height) / 2 + 1rem);
            padding-right: calc(var(--section-btn__height) / 2 + 1rem);
            line-height: var(--section-btn__line-height);
            font-size: 1rem;
            overflow: hidden;
            white-space: nowrap;
            text-overflow: ellipsis;
            color: var(--text-color__default);
            transition: color var(--anim-duration) ease;
        }

        &__progression {
            position: absolute;
            left: 1rem;
            font-size: 0.825rem;
            opacity: 0;
        }

        &__icon {
            position: absolute;
            top: 0;
            left: var(--section__bullet-offset);
            width: var(--section-btn__height);
            height: var(--section-btn__height);
            line-height: var(--section-btn__height);
            text-align: center;
            font-size: 1rem;
            transition: none;
        }
    }

    &-steps {
        // Check `@smoothHeight` animation to understand why we use this `padding-top`.
        padding-top: calc(var(--section__margin) * 2 / 3);
    }

    &-step {
        position: relative;
        padding-left: calc(var(--section__timeline-offset) + var(--section-btn__height) / 2 + 1rem);

        &+& {
            // Check `@smoothHeight` animation to understand why we don't target the first element.
            padding-top: calc(var(--section__margin) * 2 / 3);
        }

        &__icon {
            position: absolute;
            margin-top: $adjust-step-icon-position;
            left: calc(var(--section__timeline-offset) + var(--section-btn__height) / 2 - 0.5rem);
            color: var(--valid__bg-color);
            opacity: 0;
            transition: opacity var(--anim-duration) ease;
        }

        &__btn {
            font-size: 0.875rem;
            line-height: 1.5rem;
            color: var(--text-color__default);
            text-decoration: underline;
            text-decoration-color: transparent;
            text-decoration-thickness: 3px;
            text-underline-offset: 0.3em;
            transition: color var(--anim-duration) ease, text-decoration-color var(--anim-duration) ease;
        }
    }

    // ----- Modifiers -----

    &-section {
        &--current &__bullet {
            left: 0;
            width: 100%;
            background-color: var(--section-current__bg-color);
        }

        &--current &__btn {
            font-weight: bold;
            color: var(--section-current__text-color);
        }

        &--valid &__btn {
            color: var(--text-color__valid);
        }

        &--valid:not(&--last)::before {
            height: 100%;
        }

        &--valid#{&}--current &__btn {
            color: var(--valid__text-color);
        }

        &--current &__progression {
            animation: formStepperNavFadeIn var(--anim-duration) ease calc(var(--anim-duration) / 2) forwards;
        }

        &--valid &__bullet {
            background-color: var(--valid__bg-color);
        }

        &--valid &__icon {
            color: var(--valid__text-color);
        }
    }

    &-step {
        &--current &__btn {
            text-decoration-color: var(--step__underline-color);
        }

        &--valid &__btn {
            color: var(--text-color__valid);
        }

        &--valid &__icon {
            opacity: 1;
        }

        &--valid#{&}--current &__btn {
            text-decoration-color: var(--valid__bg-color);
        }
    }

    // ----- Mobile -----

    @media (max-width: 1023px) {
        --section-btn__line-height: 1.25rem;
        --section-btn__padding-v: 0.825rem;

        // Note: we need to reevaluate the following variable
        --section-btn__height: calc(var(--section-btn__line-height) + var(--section-btn__padding-v) * 2);

        // Prevent wired transition when switching from desktop to mobile
        opacity: 0;
        animation: formStepperNavFadeIn var(--anim-duration) ease var(--anim-duration) forwards;

        &--overlay {
            opacity: 1;
            animation: none;
            margin: 0 4px;
        }

        &-inner {
            position: relative;

            &::before,
            &::after {
                content: '';
                position: absolute;
                z-index: 1;
                top: 0;
                bottom: 0;
                width: 5px;
            }

            &::before {
                left: 0;
                background-image: linear-gradient(to left, transparent, var(--bg-color));
            }

            &::after {
                right: 0;
                background-image: linear-gradient(to right, transparent, var(--bg-color));
            }

            &__content {
                overflow-x: auto;
                text-align: center;

                // Hide scrollbar for Chrome, Safari and Opera
                &::-webkit-scrollbar {
                    display: none;
                }

                // Hide scrollbar for IE, Edge and Firefox
                & {
                    -ms-overflow-style: none; // IE and Edge
                    scrollbar-width: none; // Firefox
                }
            }
        }

        &-sections {
            display: inline-flex;

            &::before {
                left: calc(var(--section-btn__height) / 2);
                right: calc(var(--section-btn__height) / 2);
                top: calc(var(--section-btn__height) / 2 - var(--section__timeline-width) / 2);
                border-top: var(--section__timeline-width) solid var(--timeline-color);
                border-left: none;
            }
        }

        &-section {
            padding-bottom: 0;

            &+& {
                margin-left: var(--mobile-timeline-width);
            }

            &:not(&--last)::before {
                top: calc(var(--section-btn__height) / 2 - var(--section__timeline-width) / 2);
                left: calc(var(--section-btn__height) / 2);
                border-top: var(--section__timeline-width) solid var(--valid__bg-color);
                height: auto;
                width: 0%;
                transition: width var(--anim-duration) ease;
            }

            &__bullet {
                left: 0;
            }

            &__btn {
                display: flex;
                justify-content: center;
                align-items: center;
                font-size: 0.875rem;
                min-width: var(--section-btn__height);
                padding-left: calc(var(--section-btn__height) * 0.3);
                padding-right: 0;
                transition: padding calc(var(--anim-duration)) ease;
            }

            &__progression {
                position: relative;
                left: auto;
                animation: none;
                overflow: hidden;
                opacity: 0;
                margin-right: 0.625rem;
            }

            &__icon {
                position: relative;
                top: auto;
                left: auto;
                width: 1rem;
                height: 1rem;
                line-height: 1rem;
                display: inline-flex;
                align-items: center;
                justify-content: center;
                vertical-align: middle;
            }

            &__title {
                overflow: hidden;
                opacity: 0;
                margin-left: 0.625rem;
            }

            &__arrow {
                vertical-align: middle;
                display: inline-block;
                transition: transform var(--anim-duration) ease;

                &--open {
                    transform: scale(-1);
                }
            }

            &--valid:not(&--last)::before {
                width: 100%;
            }

            &--current &__btn {
                padding-left: 1.25rem;
                padding-right: 1.25rem;
            }

            &--current &__title {
                animation: formStepperNavFadeIn var(--anim-duration) ease calc(var(--anim-duration) / 2) forwards;
            }
        }

        &-steps {
            $steps-offset: 6px;

            max-width: 50vw;
            margin-top: $steps-offset;
            padding: 1.125rem 0;

            box-sizing: border-box;
            box-shadow: var(--mobile-steps__box-shadow);
            border-radius: 4px;
            border: 1px solid var(--mobile-steps__border-color);
            background-color: var(--mobile-steps__bg-color);

            &::after {
                content: '';
                position: absolute;
                z-index: 1;
                top: calc(-5.6px + #{$steps-offset});
                width: 11px;
                height: 11px;
                transform: rotate(-45deg);
                border-top-right-radius: 4px;
                border-width: 1px 1px 0 0;
                border-style: solid;
                border-color: var(--mobile-steps__border-color);
                background-color: var(--mobile-steps__bg-color);
            }
        }

        // on left side
        &-steps--left::after {
            left: 1.125rem;
        }

        // on right side
        &-steps--right::after {
            right: 1.125rem;
        }

        &-step {
            display: flex;
            align-items: baseline;
            padding: 0 2.5rem 0 1rem !important;

            &__icon {
                position: relative;
                margin-top: 0;
                top: $adjust-step-icon-position;
                left: 0;
                margin-right: 0.5rem;
            }

            &__btn {
                padding: 0.375rem 0;
                overflow: hidden;
                text-overflow: ellipsis;
                white-space: nowrap;
            }
        }
    }
}

@keyframes formStepperNavFadeIn {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

components.templateData:
@let currentState = state();

<div class="lib-form-stepper-nav-inner">
    <div class="lib-form-stepper-nav-inner__content">
        <nav class="lib-form-stepper-nav-sections">

            @if (currentState.onboardingInfo && !libFormStepperNoOnboardingNav()) {
            <div class="lib-form-stepper-nav-section"
                [class.lib-form-stepper-nav-section--valid]="currentState.maxStepIndexViewed >= 0"
                [class.lib-form-stepper-nav-section--current]="currentState.stepIndex === -1">
                <span class="lib-form-stepper-nav-section__bullet"></span>

                <button type="button" tabindex="-1" class="lib-form-stepper-nav-section__btn"
                    (click)="navigateByStepIndex($event, currentState.onboardingInfo.index)">
                    <lib-form-stepper-section-icon class="lib-form-stepper-nav-section__icon"
                        [libFormStepperIcon]="currentState.onboardingInfo.icon"
                        [libFormStepperIsValid]="currentState.maxStepIndexViewed >= 0">
                    </lib-form-stepper-section-icon>

                    <span class="lib-form-stepper-nav-section__title lib-form-stepper-nav-section__title--width"
                        [class.lib-form-stepper-nav-section__title--expanded]="!isMobile() || currentState.stepIndex === currentState.onboardingInfo.index">
                        {{ currentState.onboardingInfo.title }}
                    </span>
                </button>
            </div>
            }

            @for (section of currentState.nav; track section.id; let sectionIndex = $index, isLastSectionIndex = $last)
            {
            @let offset = sectionStepOffset(sectionIndex);
            @let sectionValid = isSectionValid(section, offset, currentState.maxStepIndexViewed);
            @let steps = section.steps();
            <!--
          La progression ("2/4") est portée par chaque step (LibFormStepperStep.sectionProgression),
          pas par la section elle-même : on la lit donc sur le step actuellement affiché,
          uniquement quand ce step appartient bien à cette section.
        -->
            @let currentStepInSection = currentState.sectionIndex === sectionIndex
            ? steps[currentState.stepIndex - offset]
            : undefined;

            <div class="lib-form-stepper-nav-section" [class.lib-form-stepper-nav-section--valid]="sectionValid"
                [class.lib-form-stepper-nav-section--current]="currentState.sectionIndex === sectionIndex"
                [class.lib-form-stepper-nav-section--last]="!currentState.summaryInfo && isLastSectionIndex">
                <span class="lib-form-stepper-nav-section__bullet"></span>

                <button type="button" tabindex="-1" class="lib-form-stepper-nav-section__btn"
                    [attr.disabled]="(!steps.length || (offset > currentState.maxStepIndexViewed && !steps[0].field.dirty())) ? true : null"
                    (click)="navigateByStepIndex($event, offset, sectionIndex)" cdkOverlayOrigin
                    #mobileOverlayOrigin="cdkOverlayOrigin">

                    @if (currentStepInSection?.sectionProgression) {
                    <span class="lib-form-stepper-nav-section__progression">
                        {{ currentStepInSection.sectionProgression.count }}/{{
                        currentStepInSection.sectionProgression.total }}
                    </span>
                    }

                    <lib-form-stepper-section-icon class="lib-form-stepper-nav-section__icon"
                        [libFormStepperIcon]="section.icon" [libFormStepperIsValid]="sectionValid">
                    </lib-form-stepper-section-icon>

                    <span class="lib-form-stepper-nav-section__title lib-form-stepper-nav-section__title--width"
                        [class.lib-form-stepper-nav-section__title--expanded]="!isMobile() || currentState.sectionIndex === sectionIndex">
                        {{ section.title }}

                        @if (!(section.noStepsNav ?? libFormStepperNoStepsNav()) && isMobile() && steps.length >= 2 &&
                        currentState.sectionIndex === sectionIndex) {
                        <i class="lib-form-stepper-nav-section__arrow libicon-fleche-dropdown-texte"
                            [class.lib-form-stepper-nav-section__arrow--open]="isMobileOverlayOpen()"
                            aria-hidden="true">
                        </i>
                        }
                    </span>
                </button>

                @if (!(section.noStepsNav ?? libFormStepperNoStepsNav()) && currentState.sectionIndex === sectionIndex)
                {
                @if (!isMobile()) {
                <ng-container [ngTemplateOutlet]="stepsTemplate"></ng-container>
                } @else {
                <ng-template cdkConnectedOverlay [cdkConnectedOverlayOrigin]="mobileOverlayOrigin"
                    [cdkConnectedOverlayOpen]="isMobileOverlayOpen()"
                    [cdkConnectedOverlayPositions]="sectionIndex < currentState.nav.length / 2 ? mobileOverlayPosition.left : mobileOverlayPosition.right">
                    <div class="lib-form-stepper-nav lib-form-stepper-nav--overlay" animate.leave="nav-fade-out">
                        <ng-container [ngTemplateOutlet]="stepsTemplate"></ng-container>
                    </div>
                </ng-template>
                }
                }

                <ng-template #stepsTemplate>
                    @if (steps.length >= 2) {
                    <div class="lib-form-stepper-nav-steps" [class.lib-form-stepper-nav-steps--expanded]="true"
                        [class.lib-form-stepper-nav-steps--left]="sectionIndex < currentState.nav.length / 2"
                        [class.lib-form-stepper-nav-steps--right]="sectionIndex >= currentState.nav.length / 2">
                        <div class="lib-form-stepper-nav-steps__inner">
                            @for (step of steps; track step.id; let relativeIndex = $index) {
                            @let globalIndex = offset + relativeIndex;
                            @let stepValid = isStepValid(step, globalIndex, currentState.maxStepIndexViewed);

                            <div class="lib-form-stepper-nav-step" [class.lib-form-stepper-nav-step--valid]="stepValid"
                                [class.lib-form-stepper-nav-step--current]="currentState.stepIndex === globalIndex">
                                <i class="libicon-cercle-check lib-form-stepper-nav-step__icon" aria-hidden="true"></i>

                                <button type="button" tabindex="-1" class="lib-form-stepper-nav-step__btn"
                                    [attr.disabled]="isStepDisabled(step, globalIndex, currentState.maxStepIndexViewed) ? true : null"
                                    (click)="navigateByStepIndex($event, globalIndex)">
                                    {{ step.shortTitle || step.title }}
                                </button>
                            </div>
                            }
                        </div>
                    </div>
                    }
                </ng-template>
            </div>
            }

            @if (currentState.summaryInfo) {
            <div class="lib-form-stepper-nav-section lib-form-stepper-nav-section--last"
                [class.lib-form-stepper-nav-section--valid]="currentState.allStepsViewed"
                [class.lib-form-stepper-nav-section--current]="currentState.stepIndex === currentState.lastStepIndex">
                <span class="lib-form-stepper-nav-section__bullet"></span>

                <button type="button" tabindex="-1" class="lib-form-stepper-nav-section__btn"
                    [attr.disabled]="!currentState.allStepsViewed ? true : null"
                    (click)="navigateByStepIndex($event, currentState.summaryInfo.index)">
                    <lib-form-stepper-section-icon class="lib-form-stepper-nav-section__icon"
                        [libFormStepperIcon]="currentState.summaryInfo.icon"
                        [libFormStepperIsValid]="currentState.allStepsViewed">
                    </lib-form-stepper-section-icon>

                    <span class="lib-form-stepper-nav-section__title lib-form-stepper-nav-section__title--width"
                        [class.lib-form-stepper-nav-section__title--expanded]="!isMobile() || currentState.stepIndex === currentState.summaryInfo.index">
                        {{ currentState.summaryInfo.title }}
                    </span>
                </button>
            </div>
            }
        </nav>
    </div>
</div>

