import { Component, input, ViewEncapsulation } from '@angular/core';
import { LibIconName, Icon } from '@ds-design-system/ui-components/icon';

/**
 * Icône de section/step du stepper : bascule automatiquement entre l'icône
 * fournie et un check de validation, avec une animation de fondu/scale
 * à chaque changement d'état.
 */
@Component({
  selector: 'lib-form-stepper-section-icon',
  templateUrl: './stepper-section-icon.html',
  styleUrl: './stepper-section-icon.scss',
  imports: [Icon],
  encapsulation: ViewEncapsulation.None,
})
export class StepperSectionIcon {
  readonly libFormStepperIcon = input<LibIconName>();

  readonly libFormStepperIsValid = input<boolean>();

  readonly libFormStepperDisableAnimation = input<boolean>();
}

styleUrlsData.data:
// stepper-section-icon.scss
:host {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    line-height: 1;
    --lib-icon-font-size: 1em;
    // Plus de width/height/flex ici : la taille est TOUJOURS
    // imposée par le consommateur (nav, quicknav, ...) via sa propre
    // classe sur ce même élément hôte. Fixer une taille ici créerait
    // un conflit de spécificité CSS avec les classes consommatrices.
}

.lib-form-stepper-section-icon__wrapper {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    line-height: 1;
    transform-origin: center;
}

.fade-in {
    animation: fade-in-animation 250ms ease-in-out forwards;
}

.fade-out {
    animation: fade-out-animation 250ms ease-in-out forwards;
}

@keyframes fade-in-animation {
    from {
        opacity: 0;
        transform: scaleX(0);
    }

    50% {
        opacity: 0;
        transform: scaleX(0);
    }

    to {
        opacity: 1;
        transform: scaleX(1);
    }
}

@keyframes fade-out-animation {
    from {
        opacity: 1;
        transform: scaleX(1);
    }

    49% {
        opacity: 0;
        transform: scaleX(0);
    }

    to {
        opacity: 0;
        transform: scaleX(0);
    }
}

.no-animation {
    animation: none !important;
}

